{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Vol Desk Data",
    "url": "http://localhost:7801",
    "widgets_json": {
      "realized_screen": {
        "name": "Realized Vol Screen",
        "description": "Realized volatility by tenor.",
        "endpoint": "/realized-vol",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "staleTime": 1200000,
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "as_of",
                "headerName": "As Of",
                "cellDataType": "dateString"
              },
              {
                "field": "realized_pct",
                "headerName": "Realized Pct",
                "cellDataType": "number",
                "formatterFn": "percent",
                "renderFn": "greenRed"
              },
              {
                "field": "tenor",
                "headerName": "Tenor",
                "cellDataType": "text"
              }
            ]
          }
        }
      }
    }
  }
}
